const edit = $('Edit Fields').first().json;      // chat_id, pesan dari normalisasi
const sesi = $input.first().json;                // stage, draft_json dari Get sesi

// draft_json bisa berupa objek atau string, amankan keduanya
let draft = sesi.draft_json || {};
if (typeof draft === 'string') {
  try { draft = JSON.parse(draft); } catch (e) { draft = {}; }
}

const hariIni = new Date().toISOString().slice(0, 10);

const systemPrompt = `Anda asisten administrasi sekolah yang mengekstrak data
permintaan Surat Tugas dari chat. Keluarkan HANYA objek JSON
(tanpa teks lain, tanpa pagar kode).

Skema:
{"nama_petugas":[string],"kegiatan":string|null,"tempat":string|null, "pembebanan_biaya":string|null,
 "tanggal_mulai":"YYYY-MM-DD"|null,"tanggal_selesai":"YYYY-MM-DD"|null,
 "dasar":string|null,"field_kurang":[string],"pesan_klarifikasi":string|null}

Aturan:
- Field wajib: nama_petugas, kegiatan, tempat, tanggal_mulai.
- GABUNGKAN "data terkumpul" dengan info baru dari pesan; jangan hapus yang sudah ada.
- Jangan menebak NIP atau jabatan (diisi sistem dari database).
- pembebanan_biaya (sumber dana, mis. "DIPA", "BOS", "mandiri"): ekstrak bila
  disebutkan di lampiran/pesan; JANGAN masukkan ke field_kurang (opsional).
- Jika ada data kurang: isi field_kurang dan buat pesan_klarifikasi
  (Bahasa Indonesia, sopan, singkat).
- Jika "8-9 Juli 2026", isi tanggal_mulai dan tanggal_selesai.
- Jika ragu pada suatu nilai, pakai null; jangan mengarang.
Tanggal hari ini: ${hariIni}`;

const pesanUntukAi = `Data terkumpul sejauh ini (JSON):
${JSON.stringify(draft)}

Pesan baru pemohon:
${edit.pesan}`;

return [{ json: {
  system_prompt: systemPrompt,
  pesan_untuk_ai: pesanUntukAi,
  chat_id: edit.chat_id
}}];

const raw = $input.first().json;

// Ambil semua blok teks dari jawaban Claude, gabungkan
let text = Array.isArray(raw.content)
  ? raw.content.filter(b => b.type === 'text').map(b => b.text).join('\n')
  : '';

// Buang pagar kode markdown jika ada
text = text.replace(/```json/gi, '').replace(/```/g, '').trim();

let data;
try {
  data = JSON.parse(text);
} catch (e) {
  // Jika gagal parse, jangan hentikan alur — minta pengguna ulangi
  data = {
    field_kurang: ['_parse'],
    pesan_klarifikasi: 'Maaf, boleh ulangi permintaannya dalam satu pesan?'
  };
}

// Bawa terus chat_id untuk balasan di node berikutnya
data.chat_id = $('Bangun Prompt').first().json.chat_id;

return [{ json: data }];

const rows = $input.all().map(i => i.json);   // satu baris per nama diminta
const src = $('Parse Claude File').isExecuted
  ? $('Parse Claude File').first().json
  : $('Parse Claude').first().json;

const petugas = [];
const takDitemukan = [];

for (const r of rows) {
  if (r.id) {
    petugas.push({
      pegawai_id: r.id,
      nama: r.nama,
      nip: r.nip,
      pangkat: r.pangkat_golongan,
      jabatan: r.jabatan
    });
  } else {
    takDitemukan.push(r.nama_input);
  }
}

return [{ json: {
  semua_ketemu: takDitemukan.length === 0,
  petugas,
  tak_ditemukan: takDitemukan,
  kegiatan: src.kegiatan,
  tempat: src.tempat,
  tanggal_mulai: src.tanggal_mulai,
  tanggal_selesai: src.tanggal_selesai,
  dasar: src.dasar,
  pembebanan_biaya: src.pembebanan_biaya,
  chat_id: src.chat_id
}}];

