const edit = $('Edit Fields').first().json;
const sesiRow = $('Get sesi').first().json;
let draft = sesiRow.draft_json || {};
if (typeof draft === 'string') { try { draft = JSON.parse(draft); } catch (e) { draft = {}; } }

// Ambil binary secara aman (tahan untuk mode 'separate')
const binMeta = $input.first().binary.data;
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const b64 = buffer.toString('base64');
const mime = binMeta.mimeType || 'image/jpeg';

const isPdf = mime === 'application/pdf';
const blokFile = isPdf
  ? { type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: b64 } }
  : { type: 'image',    source: { type: 'base64', media_type: mime, data: b64 } };

const hariIni = new Date().toISOString().slice(0, 10);

const system = `Anda asisten administrasi sekolah. Dari lampiran surat undangan,
ekstrak data untuk Surat Tugas. Keluarkan HANYA objek JSON, tanpa teks lain.

Skema:
{"nama_petugas":[string],"kegiatan":string|null,"tempat":string|null,
 "tanggal_mulai":"YYYY-MM-DD"|null,"tanggal_selesai":"YYYY-MM-DD"|null,
 "dasar":string|null, "pembebanan_biaya":string|null, "field_kurang":[string],"pesan_klarifikasi":string|null}

Aturan:
- kegiatan, tempat, tanggal, dan dasar (nomor undangan) diambil DARI LAMPIRAN.
- nama_petugas diambil dari "Keterangan pengirim" atau "Data terkumpul", BUKAN dari
  daftar undangan di lampiran (sekolah yang menentukan siapa ditugaskan).
- pembebanan_biaya (sumber dana, mis. "DIPA", "BOS", "mandiri"): ekstrak bila
  disebutkan di lampiran/pesan; JANGAN masukkan ke field_kurang (opsional).
- Field wajib: nama_petugas, kegiatan, tempat, tanggal_mulai.
- Gabungkan dengan data terkumpul; jika ada yang kurang isi field_kurang +
  pesan_klarifikasi (Bahasa Indonesia, sopan, singkat). Jika ragu, null.
Tanggal hari ini: ${hariIni}`;

const teks = `Data terkumpul (JSON): ${JSON.stringify(draft)}
Keterangan pengirim: ${edit.caption || '(tidak ada)'}`;

return [{ json: {
  body: {
    model: 'claude-sonnet-5',
    max_tokens: 800,
    system,
    thinking: { type: 'disabled' },
    messages: [ { role: 'user', content: [ blokFile, { type: 'text', text: teks } ] } ],
  },
  chat_id: edit.chat_id
}}];

const edit = $('Edit Fields').first().json;
const sesi = $('Get sesi').first().json;
const hariIni = new Date().toISOString().slice(0,10);
let draft = sesi.draft_json || {};
if (typeof draft === 'string') { try { draft = JSON.parse(draft); } catch(e){ draft = {}; } }

const system = `Anda mengklasifikasikan maksud pesan warga sekolah kepada asisten layanan
informasi. Tentukan jenis maksudnya. Keluarkan HANYA JSON:
{"jenis":"surat_tugas"|"keterangan_aktif"|"tanya_status_kepsek"|"tanya_jadwal"|"belum_jelas","pesan_tanya":string|null,"periode_mulai":"YYYY-MM-DD"|null,"periode_selesai":"YYYY-MM-DD"|null,"kata_kunci":string|null}

Panduan:
- surat_tugas: menugaskan guru/pegawai ke kegiatan, diklat, bimtek, lomba, dsb.
- keterangan_aktif: menerangkan seorang SISWA masih aktif belajar (untuk beasiswa,
  syarat administrasi, dsb).
- tanya_status_kepsek: menanyakan keberadaan/status Kepala Sekolah (ada di sekolah,
  sedang di mana, kapan kembali).
- tanya_jadwal: menanyakan agenda/jadwal/kegiatan/libur sekolah pada suatu waktu
  (hari ini, minggu ini, bulan tertentu, kapan libur, kapan ujian, dsb).
- Jika jenis=tanya_jadwal, tentukan periode_mulai & periode_selesai dari maksud
  pengguna. "hari ini"=tanggal hari ini; "minggu ini"=Senin–Minggu pekan ini;
  "bulan ini"/"Desember"=rentang bulan itu. Jika tak disebut periode, pakai 30 hari
  ke depan dari hari ini.
Tanggal hari ini: ${hariIni}
- Untuk pertanyaan "KAPAN peristiwa tertentu" (mis. "kapan libur semester",
  "kapan ujian", "kapan MPLS"), isi kata_kunci dengan inti peristiwanya
  (mis. "libur semester", "asesmen", "MPLS"), dan biarkan periode kosong.
- Untuk pertanyaan periode ("minggu ini", "bulan Desember"), isi periode_mulai
  & periode_selesai, dan biarkan kata_kunci kosong.
- Jika belum_jelas: tidak cocok ke mana pun; buat pesan_tanya yang ramah menanyakan
  pengguna ingin dibantu apa (sebutkan layanan yang tersedia secara natural).`;

return [{ json: {
  system_prompt: system,
  pesan_untuk_ai: `Pesan pengguna: ${edit.pesan}\nData terkumpul: ${JSON.stringify(draft)}`,
  chat_id: edit.chat_id
}}];

const raw = $input.first().json;
let text = Array.isArray(raw.content)
  ? raw.content.filter(b=>b.type==='text').map(b=>b.text).join('\n') : '';
text = text.replace(/```json/gi,'').replace(/```/g,'').trim();

const SAPAAN = 'Assalamualaikum! Saya Asisten Layanan Informasi SMKN 1 Amuntai. Saya bisa bantu: mengurus Surat Tugas, Surat Keterangan Aktif siswa, menanyakan keberadaan Kepala Sekolah, atau jadwal & agenda sekolah. Ada yang bisa dibantu?';

let data;
try {
  data = JSON.parse(text);
  // Bila AI menilai belum jelas tapi tak memberi pesan, pakai sapaan default
  if (data.jenis === 'belum_jelas' && !data.pesan_tanya) {
    data.pesan_tanya = SAPAAN;
  }
} catch(e){
  data = { jenis:'belum_jelas', pesan_tanya: SAPAAN };
}
data.chat_id = $('bangun prompt klasifikasi').first().json.chat_id;
return [{ json: data }];

const raw = $input.first().json;
let text = Array.isArray(raw.content) ? raw.content.filter(b=>b.type==='text').map(b=>b.text).join('\n') : '';
text = text.replace(/```json/gi,'').replace(/```/g,'').trim();
let data;
try { data = JSON.parse(text); }
catch(e){ data = { field_kurang:['_parse'], pesan_klarifikasi:'Maaf, boleh ulangi permintaannya?' }; }
data.chat_id = $('Bangun Prompt Siswa').first().json.chat_id;
return [{ json: data }];

const rows = $input.all().map(i => i.json).filter(r => r && r.id);
const src = $('Parse Claude Siswa').first().json;

let siswa = null, pesan = null;
if (rows.length === 0) {
  pesan = `Data siswa bernama "${src.nama_siswa}" tidak ditemukan. Mohon kirim nama lengkap sesuai data sekolah.`;
} else if (rows.length > 1 && !src.kelas) {
  pesan = `Ada lebih dari satu siswa bernama "${src.nama_siswa}". Mohon sebutkan kelasnya juga.`;
} else {
  siswa = src.kelas
    ? (rows.find(r => (r.kelas||'').toLowerCase() === (src.kelas||'').toLowerCase()) || rows[0])
    : rows[0];
}

return [{ json: {
  ketemu: !!siswa,
  pesan,
  siswa,
  keperluan: src.keperluan || null,
  chat_id: src.chat_id
}}];

const edit = $('Edit Fields').first().json;
const sesi = $('Get sesi').first().json;
let draft = sesi.draft_json || {};
if (typeof draft === 'string') { try { draft = JSON.parse(draft); } catch(e){ draft = {}; } }

const system = `Anda asisten administrasi sekolah yang menyiapkan Surat Keterangan
Aktif Belajar untuk seorang SISWA. Dari pesan pengguna, ekstrak datanya.
Keluarkan HANYA objek JSON, tanpa teks lain.

Skema:
{"nama_siswa":string|null,"kelas":string|null,"keperluan":string|null,
 "field_kurang":[string],"pesan_klarifikasi":string|null}

Aturan:
- Field wajib: nama_siswa. (kelas & keperluan opsional — JANGAN masukkan ke field_kurang)
- kelas hanya untuk membedakan bila ada nama sama; ekstrak bila disebut.
- Jangan menebak NISN/tanggal lahir/alamat — diambil sistem dari database siswa.
- GABUNGKAN dengan data terkumpul; jangan hapus yang sudah ada.
- Jika nama_siswa belum ada, isi field_kurang + pesan_klarifikasi (sopan, singkat).`;

return [{ json: {
  system_prompt: system,
  pesan_untuk_ai: `Pesan pengguna: ${edit.pesan}\nData terkumpul: ${JSON.stringify(draft)}`,
  chat_id: edit.chat_id
}}];

const sesi = $input.first().json;             // dari Get sesi (via Switch)
let d = sesi.draft_json || {};
if (typeof d === 'string') { try { d = JSON.parse(d); } catch(e){ d = {}; } }

const chat_id = $('Edit Fields').first().json.chat_id;

return [{ json: {
  chat_id,
  siswa_id: d.siswa ? d.siswa.id : null,
  keperluan: d.keperluan || null
}}];

parameters.query:
SELECT status, keterangan, estimasi_kembali,
       EXTRACT(EPOCH FROM (now() - diperbarui_pada))::int AS detik_lalu
FROM status_kepsek WHERE id = 1;

