={{ (() => {
  const s = $json;
  const menit = Math.round((s.detik_lalu || 0) / 60);
  const lalu = menit < 1 ? 'baru saja' : menit < 60 ? menit + ' menit lalu'
    : Math.round(menit/60) + ' jam lalu';
  let t = 'Saat ini Kepala Sekolah: ' + s.status + '.';
  if (s.estimasi_kembali) t += ' Perkiraan kembali pukul ' + s.estimasi_kembali + '.';
  if (s.keterangan) t += ' (' + s.keterangan + ')';
  t += '\n\nDiperbarui ' + lalu + '.';
  return t;
})() }}

={{ (() => {
  const rows = $input.all().map(i => i.json).filter(r => r && r.judul);
  if (!rows.length) return 'Tidak ada agenda terjadwal pada periode tersebut.';
  const bulan = ['Jan','Feb','Mar','Apr','Mei','Jun','Jul','Agu','Sep','Okt','Nov','Des'];
  const fmt = s => { const d = new Date(s); return d.getDate() + ' ' + bulan[d.getMonth()]; };
  const baris = rows.map(r => {
    const tgl = r.tanggal_mulai === r.tanggal_selesai ? fmt(r.tanggal_mulai)
      : fmt(r.tanggal_mulai) + '–' + fmt(r.tanggal_selesai);
    return '• ' + tgl + ': ' + r.judul;
  }).join('\n');
  return 'Agenda sekolah:\n\n' + baris;
})() }}
